body.script:
      (function () {
        var AUTH_KEYS = ['gp:user', 'gp:token', 'gp:rememberMe', 'gp:activeTenantId']
        function clearAuthStorage() {
          try {
            AUTH_KEYS.forEach(function (k) {
              localStorage.removeItem(k)
              sessionStorage.removeItem(k)
            })
          } catch (e) {}
        }
        if (/[?&]reset=1(?:&|$)/.test(location.search)) {
          clearAuthStorage()
          try {
            var u = new URL(location.href)
            u.searchParams.delete('reset')
            location.replace(u.pathname + u.search + u.hash)
          } catch (e) {
            location.replace('/login')
          }
        }
        window.__RL_CLEAR_AUTH__ = clearAuthStorage
        window.__RL_APP_MOUNTED__ = false
        window.addEventListener('rl-app-mounted', function () {
          window.__RL_APP_MOUNTED__ = true
        })
        var shown = false
        function showBootError(msg) {
          if (shown || window.__RL_APP_MOUNTED__) return
          shown = true
          var root = document.getElementById('root')
          if (!root) return
          root.innerHTML =
            '
' +
            '
App did not start' +
            '
' +
            (msg || 'JavaScript failed to load.') +
            '' +
            'Clear session & sign in'
          var btn = document.getElementById('rl-clear-auth-btn')
          if (btn) {
            btn.onclick = function () {
              clearAuthStorage()
              location.replace('/login?reset=1')
            }
          }
        }
        window.addEventListener('error', function (e) {
          if (e.message) showBootError(e.message)
        })
        window.addEventListener('unhandledrejection', function (e) {
          var reason = e.reason && (e.reason.message || String(e.reason))
          if (reason) showBootError(reason)
        })
        setTimeout(function () {
          var root = document.getElementById('root')
          if (root && !root.hasChildNodes() && !window.__RL_APP_MOUNTED__) showBootError()
        }, 12000)
      })()
